namespace sv_36006000a75f404ba019fb213352d3e5.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

public record ThemeInfo(Theme Theme, string AccentColor);

using Microsoft.AspNetCore.Components;

namespace sv_36006000a75f404ba019fb213352d3e5.Services;

/// <summary>
/// Scoped service that holds per-circuit theme state and notifies
/// both event subscribers and the CascadingValueSource on changes.
/// </summary>
public class ThemeService
{
    private readonly CascadingValueSource<ThemeInfo> _cascadingSource;

    public ThemeService(CascadingValueSource<ThemeInfo> cascadingSource)
    {
        _cascadingSource = cascadingSource;
    }

    public Theme Theme { get; private set; } = Theme.Light;
    public string AccentColor { get; private set; } = "#0d6efd";

    /// <summary>
    /// Fired after any property changes. Components should subscribe
    /// in OnInitialized and unsubscribe in Dispose.
    /// </summary>
    public event Action? OnChange;

    public async Task SetThemeAsync(Theme theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        await NotifyAsync();
    }

    public async Task SetAccentColorAsync(string accentColor)
    {
        if (AccentColor == accentColor) return;
        AccentColor = accentColor;
        await NotifyAsync();
    }

    public async Task SetAllAsync(Theme theme, string accentColor)
    {
        Theme = theme;
        AccentColor = accentColor;
        await NotifyAsync();
    }

    public ThemeInfo CurrentInfo => new(Theme, AccentColor);

    private async Task NotifyAsync()
    {
        // Push updated value to all [CascadingParameter] subscribers
        await _cascadingSource.NotifyChangedAsync(CurrentInfo);
        // Also fire the event for components using @inject + OnChange
        OnChange?.Invoke();
    }
}

