arguments.file_text:
@* Displays current theme in the static header area.
   Uses [CascadingParameter] so it updates via CascadingValueSource
   even though MainLayout is statically rendered. *@

<span class="theme-indicator" style="color: @Theme?.AccentColor;">
    @ThemeIcon @Theme?.Theme
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string ThemeIcon => Theme?.Theme switch
    {
        Services.Theme.Dark => "🌙",
        Services.Theme.System => "💻",
        _ => "☀️"
    };
}

@page "/settings"
@rendermode InteractiveServer
@using sv_36006000a75f404ba019fb213352d3e5.Services
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label fw-bold">Theme</label>
    <div class="btn-group d-block" role="group">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            var isActive = t == _selectedTheme;
            <button class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => SelectTheme(t)">
                @t
            </button>
        }
    </div>
</div>

<div class="mb-3">
    <label class="form-label fw-bold" for="accent">Accent Color</label>
    <input id="accent" type="color" class="form-control form-control-color"
           value="@_accentColor" @onchange="OnAccentChanged" />
</div>

<div class="alert mt-4" style="border-left: 4px solid @_accentColor;">
    Preview — the header indicator and all themed components update instantly.
</div>

@code {
    private Theme _selectedTheme;
    private string _accentColor = "#0d6efd";

    protected override void OnInitialized()
    {
        _selectedTheme = ThemeService.Theme;
        _accentColor = ThemeService.AccentColor;
        ThemeService.OnChange += OnThemeChanged;
    }

    private async Task SelectTheme(Theme theme)
    {
        _selectedTheme = theme;
        await ThemeService.SetThemeAsync(theme);
    }

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        _accentColor = e.Value?.ToString() ?? _accentColor;
        await ThemeService.SetAccentColorAsync(_accentColor);
    }

    private void OnThemeChanged() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeService.OnChange -= OnThemeChanged;
}

